package tv.vela.launcher;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.database.Cursor;
import android.media.tv.*;
import android.os.*;
import java.io.*;
import java.text.SimpleDateFormat;
import java.util.*;
import org.json.JSONObject;

/** Common search never inventories images or retains a media catalogue. Each source returns a small page. */
abstract class VelaToolsData implements VelaHub.Host {
    final Activity activity;
    VelaToolsData(Activity a){activity=a;}
        public JSONObject mobileState(int page)throws Exception{
        if(page<0||page>1000)throw new IOException();JSONObject out=new JSONObject().put("full",!activity.getPackageName().endsWith(".lite")).put("scale",VelaReading.choice(activity,"text",2));org.json.JSONArray rows=new org.json.JSONArray(),apps=new org.json.JSONArray(),tv=new org.json.JSONArray();for(String key:VelaLayout.order(activity))if(!activity.getPackageName().endsWith(".lite")||Arrays.asList("inputs","tv","apps").contains(key))rows.put(new JSONObject().put("key",key).put("title",VelaLayout.label(key)).put("visible",VelaLayout.visible(activity,key)));int n=0;Set<String> seen=new HashSet<>();List<ResolveInfo> installed=new ArrayList<>();PackageManager pm=activity.getPackageManager();for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(ResolveInfo info:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(category),0))if(info.activityInfo!=null&&seen.add(info.activityInfo.packageName))installed.add(info);List<String> order=VelaLayout.apps(activity);installed.sort(Comparator.comparingInt(info->{int at=order.indexOf(info.activityInfo.packageName);return at<0?10000:at;}));for(ResolveInfo info:installed)if(n++>=page*12&&apps.length()<12)apps.put(new JSONObject().put("name",info.loadLabel(pm)).put("pkg",info.activityInfo.packageName));try{for(VelaHub.Hit h:channels("",page,new CancellationSignal()))tv.put(new JSONObject().put("id",((LiveTvData.Channel)h.value).id).put("name",h.title));}catch(Exception unavailable){}return out.put("rows",rows).put("apps",apps).put("channels",tv);
    }
    public void mobileAction(JSONObject data)throws Exception{String op=data.getString("op");if(op.equals("reading")){int v=data.getInt("value");if(v<0||v>2)throw new IOException();VelaReading.prefs(activity).edit().putInt("text",v).commit();}else if(op.equals("appMove"))VelaLayout.moveApp(activity,data.getString("pkg"),data.getInt("direction"));else if(op.equals("pin")||op.equals("pinMove"))pin(data);else if(op.equals("folder"))VelaLayout.folder(activity,data.getString("name"),data.getString("app"));else if(op.equals("row")||op.equals("move")){String key=data.getString("key");if(!VelaLayout.ROWS.contains(key))throw new IOException();if(op.equals("row"))VelaLayout.toggle(activity,key);else{int direction=data.getInt("direction");if(Math.abs(direction)!=1)throw new IOException();VelaLayout.move(activity,key,direction);}}else if(op.equals("favorite")){String id=data.getString("id");boolean found=false;for(VelaHub.Hit h:channels("",data.getInt("page"),new CancellationSignal()))if(((LiveTvData.Channel)h.value).id.equals(id)){favorite((LiveTvData.Channel)h.value);found=true;break;}if(!found)throw new IOException();}else if(op.equals("source"))source(data);else throw new IOException();VelaWorkspace.registry(activity).edit().putLong("revision",System.currentTimeMillis()).commit();}
    void pin(JSONObject data)throws Exception{throw new IOException("No pinned sidebar in Lite");}
    void source(JSONObject data)throws Exception{throw new IOException("No IPTV in Lite");}
    void favorite(LiveTvData.Channel ch)throws Exception{throw new IOException();}
    abstract List<VelaHub.Hit> channels(String query,int page,CancellationSignal signal)throws Exception;
    List<VelaHub.Hit> media(String query,int page,CancellationSignal signal)throws Exception{return Collections.emptyList();}
    private static boolean match(String s,String q){return VelaWorkspace.normal(s).contains(VelaWorkspace.normal(q));}
    private static String t(String en,String es){return VelaWorkspace.t(en,es);}
    @Override public List<VelaHub.Hit> search(String query,int page,CancellationSignal signal)throws Exception{
        if(query.trim().isEmpty()||query.length()>80||page<0||page>1000)return Collections.emptyList();VelaHub.Hits out=new VelaHub.Hits();PackageManager pm=activity.getPackageManager();TreeMap<String,ResolveInfo> apps=new TreeMap<>();Set<String> seen=new HashSet<>();
        for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(ResolveInfo info:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(category),0)){signal.throwIfCanceled();if(info.activityInfo==null||!info.activityInfo.enabled)continue;String pkg=info.activityInfo.packageName;if(!pkg.equals(activity.getPackageName())&&seen.add(pkg)){String label=info.loadLabel(pm).toString();if(match(label,query))apps.put(VelaWorkspace.normal(label)+"|"+pkg,info);}}
        int at=0;for(ResolveInfo info:apps.values()){if(at>=page*4&&at<(page+1)*4){Intent open=new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(info.activityInfo.packageName,info.activityInfo.name)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);out.add(new VelaHub.Hit(t("App","Aplicación"),info.loadLabel(pm).toString(),t("Open application","Abrir aplicación"),open));}at++;}
        out.more=at>(page+1)*4;at=0;for(TvInputs.Entry entry:TvInputs.list(activity)){signal.throwIfCanceled();if(match(entry.title+" "+entry.port,query)){if(at>=page*4&&at<(page+1)*4)out.add(new VelaHub.Hit("HDMI",entry.title,entry.port+" · "+TvInputs.status(entry.state),entry));at++;}}
        out.more|=at>(page+1)*4;try{List<VelaHub.Hit> found=channels(query,page,signal);out.addAll(found);out.more|=found instanceof VelaHub.Hits?((VelaHub.Hits)found).more:found.size()>=12;}catch(Exception unavailable){if(signal.isCanceled()||Thread.currentThread().isInterrupted())throw unavailable;}
        signal.throwIfCanceled();try{List<VelaShows.Airing> programmes=airings(query,page,signal);SimpleDateFormat date=new SimpleDateFormat("EEE d HH:mm",Ui.locale());out.more|=programmes.size()>=24;for(int i=0;i<programmes.size();i++){VelaShows.Airing p=programmes.get(i);out.add(new VelaHub.Hit(t("Programme","Programa"),p.title,p.channel+" · "+date.format(new Date(p.start*1000)),p));}}catch(SecurityException unavailable){}
        signal.throwIfCanceled();try{List<VelaHub.Hit> found=media(query,page,signal);out.addAll(found);out.more|=found instanceof VelaHub.Hits?((VelaHub.Hits)found).more:found.size()>=24;}catch(Exception unavailable){if(signal.isCanceled()||Thread.currentThread().isInterrupted())throw unavailable;}
        signal.throwIfCanceled();return out;
    }
    static Map<Long,String> nativeNames(Context c,String tuner,CancellationSignal signal){Map<Long,String> names=new HashMap<>();try(Cursor rows=c.getContentResolver().query(TvContract.Channels.CONTENT_URI,new String[]{"_id","input_id","display_name","browsable","locked"},null,null,null,signal)){for(int i=0;rows!=null&&rows.moveToNext()&&i<5000;i++){signal.throwIfCanceled();if(rows.getInt(3)==1&&rows.getInt(4)==0&&(tuner==null||tuner.equals(rows.getString(1))))names.put(rows.getLong(0),VelaWorkspace.clean(rows.getString(2),120));}}return names;}
    static List<VelaShows.Airing> nativeAirings(Context c,Map<Long,String> names,String query,int page,CancellationSignal signal){Map<String,Long> offsets=VelaGuideFix.offsets(c);List<VelaShows.Airing> out=new ArrayList<>();long now=System.currentTimeMillis()/1000;int skipped=0;try(Cursor rows=c.getContentResolver().query(TvContract.Programs.CONTENT_URI,new String[]{"channel_id","start_time_utc_millis","end_time_utc_millis","title"},null,null,"start_time_utc_millis ASC",signal)){for(int count=0;rows!=null&&rows.moveToNext()&&count<20000;count++){signal.throwIfCanceled();String name=names.get(rows.getLong(0)),title=rows.getString(3);long offset=name==null?0:offsets.getOrDefault(TvChannelNames.match(name),0L);long start=rows.getLong(1)/1000+offset,end=rows.getLong(2)/1000+offset;if(name==null||title==null||end<=now||start>=now+48*3600||end<=start||!match(title,query))continue;if(skipped++<page*24)continue;out.add(new VelaShows.Airing(title,name,start,end));if(out.size()>=24)break;}}catch(SecurityException denied){throw denied;}catch(RuntimeException unavailable){}return out;}
    static List<VelaShows.Airing> merge(List<VelaShows.Airing> a,List<VelaShows.Airing> b){List<VelaShows.Airing> out=new ArrayList<>();Set<String> seen=new HashSet<>();for(List<VelaShows.Airing> list:Arrays.asList(a,b))for(VelaShows.Airing p:list)if(seen.add(VelaWorkspace.normal(p.channel)+"|"+p.start+"|"+VelaShows.identity(p.title)))out.add(p);out.sort(Comparator.comparingLong(p->p.start));return out.size()>64?new ArrayList<>(out.subList(0,64)):out;}
    @Override public String diagnosis(CancellationSignal cancel)throws Exception{
        StringBuilder report=new StringBuilder();PackageInfo pkg=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);report.append("Vela · ").append(pkg.versionName).append('\n').append(Build.MANUFACTURER).append(" · ").append(Build.MODEL).append("\nAndroid ").append(Build.VERSION.RELEASE).append(" · API ").append(Build.VERSION.SDK_INT).append('\n');ActivityManager manager=(ActivityManager)activity.getSystemService(Context.ACTIVITY_SERVICE);if(manager!=null)report.append(t("Low RAM device: ","Dispositivo de RAM reducida: ")).append(manager.isLowRamDevice()?t("yes","sí"):"no").append('\n');report.append(String.format(Locale.ROOT,t("Vela process (PSS): %.1f MB\n","Proceso de Vela (PSS): %.1f MB\n"),Debug.getPss()/1024f));String build=LiveTvData.hash(Build.FINGERPRINT);SharedPreferences health=activity.getSharedPreferences("vela-device-health",0);String previous=health.getString("build",build);boolean changed=!build.equals(previous);if(changed||!health.contains("build"))health.edit().putString("build",build).putBoolean("system-changed",changed).apply();report.append(t("System update since last check: ","Cambio del sistema desde la última revisión: ")).append(health.getBoolean("system-changed",false)?t("yes","sí"):"no").append('\n');ResolveInfo home=activity.getPackageManager().resolveActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),PackageManager.MATCH_DEFAULT_ONLY);report.append(t("Default home: ","Inicio predeterminado: ")).append(home!=null&&home.activityInfo!=null?home.activityInfo.packageName:t("not reported","no publicado")).append('\n');report.append(t("Update installation permission: ","Permiso de instalación de actualizaciones: ")).append(activity.getPackageManager().canRequestPackageInstalls()?t("granted","concedido"):t("not granted","sin conceder")).append('\n');report.append(t("TV listings permission: ","Permiso de guía: ")).append(activity.checkSelfPermission("android.permission.READ_TV_LISTINGS")==PackageManager.PERMISSION_GRANTED?t("granted","concedido"):t("not granted","sin conceder")).append('\n');cancel.throwIfCanceled();try{android.net.ConnectivityManager connectivity=(android.net.ConnectivityManager)activity.getSystemService(Context.CONNECTIVITY_SERVICE);android.net.NetworkCapabilities caps=connectivity==null?null:connectivity.getNetworkCapabilities(connectivity.getActiveNetwork());report.append(t("Network: ","Red: ")).append(caps==null?t("offline","sin conexión"):caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_ETHERNET)?"Ethernet":caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi":t("connected","conectada")).append('\n');}catch(SecurityException unavailable){report.append(t("Network status unavailable\n","Estado de red no disponible\n"));}int active=0,total=0;for(TvInputs.Entry e:TvInputs.list(activity)){total++;if(e.state==TvInputs.CONNECTED)active++;}report.append(t("HDMI ports reported: ","Puertos HDMI publicados: ")).append(total).append(" · ").append(active).append(t(" connected"," conectados")).append('\n');TvInputManager tv=(TvInputManager)activity.getSystemService(Context.TV_INPUT_SERVICE);int tuners=0;if(tv!=null)for(TvInputInfo input:tv.getTvInputList())if(input.getType()==TvInputInfo.TYPE_TUNER)tuners++;report.append(t("Tuner inputs: ","Entradas de sintonizador: ")).append(tuners).append('\n');File guide=new File(activity.getCacheDir(),activity.getPackageName().endsWith(".lite")?"antenna-epg/programmes.db":"tv-guide/xmltv.db");report.append(t("Saved guide: ","Guía guardada: ")).append(guide.isFile()?String.format(Locale.ROOT,"%.1f MB",guide.length()/1048576f):t("not loaded","sin cargar")).append('\n').append(t("Firmware controls signal, HDMI-CEC and native tuning. This report does not test physical picture or sound.","El firmware controla la señal, HDMI-CEC y la sintonización. Este informe no comprueba físicamente la imagen ni el sonido."));return report.toString();
    }
}
